// spec: .qa/e2e/specs/content-filter.md 1.2 · тикет #2ee07c55 (AC 4, 5, 7)
// Две роли: user4 трижды отправляет одинаковое «QA-AUTO …» в общий чат (тем же запросом, что приложение) →
// admin видит в «לבדיקה» ровно одну пометку — на третьем сообщении: «ספאם», «אותו טקסט נשלח 3 פעמים ב־10 דקות».
// @data: в finally user4 удаляет все три сообщения (пометка уходит вместе с ними).
import { test, expect } from '@playwright/test';
import type { Page } from '@playwright/test';
import { ADMIN_URL, adminAs, appApi, cId, closeAdmin, closeApp, contentDetail, contentQueue, deleteCommunity, iphoneAs, qaText, sendCommunity } from '../moderation-menu/mod-helpers';
import type { Api } from '../_shared/api';

test.describe('סינון תוכן אוטומטי בסיסי', () => {
  test('Одинаковое сообщение 3 раза в общем чате — одна пометка «ספאם» на третьем @desktop @data (#2ee07c55)', async ({ browser }) => {
    test.setTimeout(150_000);
    const user = await iphoneAs(browser, 'user4');
    let admin: Page | undefined;
    let api: Api | undefined;
    const ids: string[] = [];
    const text = qaText('2ee07c55', 'spam');
    try {
      api = await appApi(user);
      for (let i = 0; i < 3; i++) ids.push(await sendCommunity(api, text));

      admin = await adminAs(browser);
      await admin.goto(`${ADMIN_URL}/content?tab=review`);
      const rows = contentQueue(admin).getByRole('link').filter({ hasText: text });
      await expect(rows).toHaveCount(1);
      await expect(rows).toContainText(cId(ids[2]));
      await expect(rows).toContainText("הודעה בקהילה · צ'אט קהילתי");
      await rows.click();
      const why = contentDetail(admin).getByRole('listitem').filter({ hasText: 'סינון אוטומטי:' });
      await expect(why).toContainText(/סיבה:\s*ספאם/);
      await expect(why).toContainText('סינון אוטומטי: אותו טקסט נשלח 3 פעמים ב־10 דקות');

      // Очистка
      await deleteCommunity(api, ids);
      ids.length = 0;
      await admin.goto(`${ADMIN_URL}/content?tab=review`);
      await expect(contentQueue(admin).getByRole('tab', { name: /^לבדיקה/ })).toHaveAttribute('aria-selected', 'true');
      await expect(contentQueue(admin).getByText(text)).toHaveCount(0);
    } finally {
      if (api) await deleteCommunity(api, ids);
      await closeAdmin(admin);
      await closeApp(user, 'user4');
    }
  });
});
